code.text:
# what the ai-agents store may read: our own folder, nothing else
path "kvv2/data/infrastructure/ai-agents/*" {
  capabilities = ["read"]
}

# what vault-store's login may read today: everything in the mount
path "kvv2/data/*" {
  capabilities = ["read"]
}

follow.do:
printf 'path "kvv2/data/infrastructure/ai-agents/*" {
  capabilities = ["read"]
}
' | kubectl -n vault exec -i vault -- vault policy write ai-agents-read - && kubectl create namespace ai-agents && kubectl -n vault exec vault -- vault token create -policy=ai-agents-read -field=token | kubectl -n ai-agents create secret generic vault-token --from-file=token=/dev/stdin
